-- MAJ98 : deux sections supplémentaires, aucun remplacement des catalogues existants.
BEGIN;
DO $migration$
DECLARE f record; definition text; changed text; m text[]; candidate text; extended text; additions text; kind text; n integer:=0;
BEGIN
 IF to_regclass('workshop_private.catalog75') IS NULL OR to_regclass('workshop_private.product_codes83') IS NULL THEN RAISE EXCEPTION 'Les migrations des catalogues (75 à 92) doivent être installées avant la 98.'; END IF;
 -- Étendre uniquement les listes littérales de sections existantes.
 -- Ni les conditions de rôle ni les corps des opérations ne sont remplacés.
 FOR f IN SELECT p.oid FROM pg_proc p JOIN pg_namespace ns ON ns.oid=p.pronamespace
 WHERE ns.nspname IN ('public','workshop_private') AND p.prokind='f' AND ns.nspname<>'pg_catalog'
 AND (p.proname LIKE '%catalog%' OR p.proname LIKE '%settings81%' OR p.prosrc LIKE '%catalog.pneus%') LOOP
  definition:=pg_get_functiondef(f.oid);changed:=definition;
  FOR m IN SELECT regexp_matches(definition,'(\([^()\[\]]*\)|ARRAY\[[^\[\]]*\])','g') LOOP
   candidate:=m[1];kind:=NULL;
   IF candidate ~ '''Pneus''' AND candidate ~ '''(5gaz|Freins, transmissions, roulements)''' THEN kind:='sections';
   ELSIF candidate ~ '''catalog.pneus''' THEN kind:='settings'; END IF;
   IF kind IS NULL THEN CONTINUE; END IF;
   -- A list must contain ONLY quoted text literals, commas and optional ::text casts.
   IF regexp_replace(candidate,'^ARRAY\[|^\(|\]$|\)$','','g') !~ $rx$^\s*'([^']|'')*'(::text)?(\s*,\s*'([^']|'')*'(::text)?)*\s*$rx$ THEN CONTINUE; END IF;
   additions:=CASE WHEN kind='sections' THEN ', ''Vidange'', ''Phare, ampoule, Pare brise, élec''' ELSE ', ''catalog.vidange'', ''catalog.eclairage''' END;
   IF (kind='sections' AND candidate LIKE '%''Vidange''%') OR (kind='settings' AND candidate LIKE '%''catalog.vidange''%') THEN CONTINUE; END IF;
   extended:=left(candidate,length(candidate)-1)||additions||right(candidate,1);
   changed:=replace(changed,candidate,extended);
  END LOOP;
  IF changed<>definition THEN EXECUTE changed;n:=n+1; END IF;
 END LOOP;
 RAISE NOTICE '% fonctions de catalogue/réglages adaptées ; droits et signatures conservés.',n;
END $migration$;
-- Les UUID sont stables : une réexécution ne recrée pas les articles et ne remet
-- pas à zéro les noms, photos, ruptures ou restrictions modifiés dans l'application.
CREATE TEMP TABLE seed98(id uuid, section text, name text, code text, photo bytea, position integer) ON COMMIT DROP;
WITH added AS (
 SELECT id,section,name,photo,position,false FROM seed98 ON CONFLICT(id) DO NOTHING RETURNING id
)
SELECT s.id,s.code FROM seed98 s JOIN added a ON a.id=s.id ON CONFLICT(product_id) DO NOTHING;
UPDATE workshop_private.catalog75_rev SET rev=rev+1 WHERE section IN ('Vidange','Phare, ampoule, Pare brise, élec');
NOTIFY pgrst, 'reload schema';
COMMIT;
SELECT section,count(*) AS articles FROM workshop_private.catalog75 WHERE section IN ('Vidange','Phare, ampoule, Pare brise, élec') GROUP BY section ORDER BY section;
